import { useReducer, useState } from "react";
import Reducer, { initialState } from "./reducer";
import { DEVELOPER, NUMBER, AGE, USER, SINGLE } from "./actionTypes";
import Modal from "./components/Modal/Modal";

import "./App.css";

function App() {
  const [input, setInput] = useState("");
  const [state, dispatch] = useReducer(
    Reducer((openClose = openClose)),
    initialState
  );

  function forInput(e) {
    setInput(e.target.value);
  }

  function forButton(type) {
    dispatch({ type: type, payload: input });
    setInput("");
  }

  return (
    <div className="appContainer">
      <div className="mainApp">
        <div>
          <form className="buttons">
            <div className="fieldDiv">
              <p className="fieldP">Enter Username</p>
              <input className="field" id="field" onChange={forInput} />
            </div>
            <button
              className="fieldBtn"
              type="button"
              onClick={() => {
                forButton(DEVELOPER);
              }}
            >
              ADD DEVELOPER
            </button>
            <button className="fieldBtn" type="button">
              SHUFFLE ARRAY
            </button>
            <button
              className="fieldBtn"
              type="button"
              onClick={() => {
                forButton(NUMBER);
              }}
            >
              ADD NUMBER
            </button>
            <button
              className="fieldBtn"
              type="button"
              onClick={() => {
                forButton(SINGLE);
              }}
            >
              REMOVE SINGLE DIGITS
            </button>
            <button
              className="fieldBtn"
              type="button"
              onClick={() => {
                forButton(USER);
              }}
            >
              CHANGE USER
            </button>
            <button
              className="fieldBtn"
              type="button"
              onClick={() => {
                forButton(AGE);
              }}
            >
              ADD AGE
            </button>
          </form>
        </div>
        <div className="output">
          <p>Output</p>
          <p>{JSON.stringify(state)}</p>
        </div>
      </div>
    </div>
  );
}

export default App;
